section.sourcecode:
SecureMimeMessageV3dot1
{ iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs-9(9) smime(16) modules(0) msg-v3dot1(21) }
DEFINITIONS IMPLICIT TAGS ::=
BEGIN
IMPORTS
-- 暗号メッセージ構文 [CMS] SubjectKeyIdentifier, IssuerAndSerialNumber, RecipientKeyIdentifier FROM CryptographicMessageSyntax { iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs-9(9) smime(16) modules(0) cms-2001(14) };
-- id-aaは、S/MIMEワーキンググループが作成したすべての新しい認証済み -- 属性と非認証属性を含むアークです。
id-aa OBJECT IDENTIFIER ::= {iso(1) member-body(2) usa(840) rsadsi(113549) pkcs(1) pkcs-9(9) smime(16) attributes(2)}
-- S/MIME Capabilitiesは、理解できる対称暗号の能力を通知する方法を -- 提供します。アルゴリズムは優先順に並べ、種類ごとにグループ化する -- べきです（SHOULD）。
smimeCapabilities OBJECT IDENTIFIER ::= {iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs-9(9) 15}
SMIMECapability ::= SEQUENCE { capabilityID OBJECT IDENTIFIER, parameters ANY DEFINED BY capabilityID OPTIONAL }
SMIMECapabilities ::= SEQUENCE OF SMIMECapability
-- Encryption Key Preferenceは、優先する暗号化証明書を通知する方法を -- 提供します。
id-aa-encrypKeyPref OBJECT IDENTIFIER ::= {id-aa 11}
SMIMEEncryptionKeyPreference ::= CHOICE { issuerAndSerialNumber [0] IssuerAndSerialNumber, receipentKeyId [1] RecipientKeyIdentifier, subjectAltKeyIdentifier [2] SubjectKeyIdentifier }
-- "receipentKeyId"はつづりが誤っていますが、歴史的な理由から -- そのままにしています。
id-smime OBJECT IDENTIFIER ::= { iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs-9(9) 16 }
id-cap OBJECT IDENTIFIER ::= { id-smime 11 }
-- preferBinaryInside OIDは、CMSラッパーの内側がバイナリー -- エンコーディングであるメッセージを受信できることを示します。 -- preferBinaryInside属性の値フィールドはABSENTです。
id-cap-preferBinaryInside OBJECT IDENTIFIER ::= { id-cap 1 }
-- 以下は、S/MIME v3で使用するOIDのリストです。
-- [RFC3370]、[RFC5754]、[RFC4056]、および[RFC3560]にない -- 署名アルゴリズム
-- -- md2WithRSAEncryption OBJECT IDENTIFIER ::= -- {iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs-1(1) -- 2}
-- -- その他の署名付き属性 -- -- signingTime OBJECT IDENTIFIER ::= -- {iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs-9(9) -- 5} -- 属性値のエンコード方法については[CMS]を参照してください。
SMIMECapabilitiesParametersForRC2CBC ::= INTEGER -- （RC2の鍵長（ビット数））
END
